-- Run from the repository root with Lua 5.4: lua5.4 bin/tests/servo_names.lua
-- lib/servo_names.lua ports wingflight-configurator's src/js/ServoNames.js.
-- The expected names below are the configurator's own namesFromRules()
-- output for the rules lib/setup_wizard_mix.lua builds in
-- bin/tests/setup_wizard_mix.lua's cases, generated by running ServoNames.js
-- under Node on 2026-11-16. When the JS changes, regenerate these and port
-- the change. Also covers lib/msp_servo_names.lua's wire format.

local ROOT = "src/wfsuite/"

local failures, checks = 0, 0
local function check(label, ok, detail)
  checks = checks + 1
  if ok then
    print("  ok    " .. label)
  else
    failures = failures + 1
    print("  FAIL  " .. label)
    if detail then print("        " .. tostring(detail)) end
  end
end

-- lib/require.lua resolves "lib/x.lua" from the script root on the radio.
-- Here every module is loaded from src/wfsuite/ instead.
package.loaded["wfsuite.lib.require"] = function(path)
  local key = "wfsuite." .. path:gsub("%.lua$", ""):gsub("/", ".")
  if package.loaded[key] then return package.loaded[key] end
  local mod = assert(loadfile(ROOT .. path))()
  package.loaded[key] = mod
  return mod
end

local mix = assert(loadfile(ROOT .. "lib/setup_wizard_mix.lua"))()
local names = package.loaded["wfsuite.lib.require"]("lib/servo_names.lua")
local codec = package.loaded["wfsuite.lib.require"]("lib/msp_servo_names.lua")

local function render(map)
  local servos = {}
  for servo in pairs(map) do servos[#servos + 1] = servo end
  table.sort(servos)
  local out = {}
  for i, servo in ipairs(servos) do out[i] = servo .. "=" .. map[servo] end
  return table.concat(out, ";")
end

local CASES = {
  {name = "regular", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", motors = 1},
    names = "0=L AIL;1=R AIL;2=ELEV;3=RUDDER"},
  {name = "regularSingleNoMotor", options = {layout = "conventional", ailerons = "single", tailControl = "elevatorOnly", motors = 0},
    names = "0=AIL;1=ELEV"},
  {name = "regularFlaps2Follow", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 2, flapsFollowAilerons = true, motors = 1},
    names = "0=L AIL;1=R AIL;2=ELEV;3=RUDDER;4=L FLAP;5=R FLAP"},
  {name = "regularFlap1", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 1, motors = 1},
    names = "0=L AIL;1=R AIL;2=ELEV;3=RUDDER;4=FLAP"},
  {name = "flaperons", options = {layout = "conventional", ailerons = "independent", tailControl = "elevatorRudder", flaps = true, flapServos = 0, motors = 1},
    names = "0=L FLPRN;1=R FLPRN;2=ELEV;3=RUDDER"},
  {name = "flaperonsNoAilerons", options = {layout = "conventional", ailerons = "none", tailControl = "elevatorRudder", flaps = true, flapServos = 0, motors = 1},
    names = "0=ELEV;1=RUDDER"},
  {name = "vtail", options = {layout = "conventional", ailerons = "independent", tailControl = "vtail", motors = 1},
    names = "0=L AIL;1=R AIL;2=L VTAIL;3=R VTAIL"},
  {name = "wingRudder", options = {layout = "flyingWing", wingYaw = "rudder", motors = 2, diffThrustYaw = true},
    names = "0=L ELEVON;1=R ELEVON;2=RUDDER"},
  {name = "wingNoYaw", options = {layout = "flyingWing", wingYaw = "none", motors = 1, flaps = true, flapServos = 1},
    names = "0=L ELEVON;1=R ELEVON;2=FLAP"},
  {name = "trainer", options = {layout = "conventional", ailerons = "none", tailControl = "elevatorRudder", motors = 1},
    names = "0=ELEV;1=RUDDER"},
}

for _, case in ipairs(CASES) do
  local got = render(names.namesFromRules(mix.buildRules(case.options)))
  check(case.name .. " matches the configurator", got == case.names, got)
end

-- Thrust vectoring: named after the axis, unless the servo is a surface too.
local tvRules = {
  {oper = 1, input = 2, output = 1, weight = 1000, weightNeg = 1000},
  {oper = 1, input = 28, output = 2, weight = 1000, weightNeg = 1000},
  {oper = 1, input = 29, output = 3, weight = 1000, weightNeg = 1000},
}
check("thrust-vector servos named by axis",
  render(names.namesFromRules(tvRules)) == "0=ELEV;1=TV PITCH;2=TV YAW",
  render(names.namesFromRules(tvRules)))

-- Three of a kind are numbered.
local three = {}
for s = 1, 3 do three[s] = {oper = 1, input = 3, output = s, weight = 1000, weightNeg = 1000} end
check("three of a kind numbered",
  render(names.namesFromRules(three)) == "0=RUDDER 1;1=RUDDER 2;2=RUDDER 3",
  render(names.namesFromRules(three)))

-- assign(): assigned servos are named (a typed name there too), a generated
-- name on a servo the mix no longer drives is cleared, a typed one is kept.
local current = {}
for s = 0, names.SERVO_COUNT - 1 do current[s] = "" end
current[3] = "MYSERVO"
current[5] = "TOWHOOK"
current[6] = "L FLAP"
current[7] = "TV ROLL"
local changed = names.assign(current, mix.buildRules(CASES[1].options))
check("assign names the mix",
  current[0] == "L AIL" and current[1] == "R AIL" and current[2] == "ELEV" and current[3] == "RUDDER",
  render(current))
check("assign keeps a typed name off the mix", current[5] == "TOWHOOK", current[5])
check("assign clears generated names off the mix", current[6] == "" and current[7] == "", current[6] .. "|" .. current[7])
check("assign reports exactly the changed servos", table.concat(changed, ",") == "0,1,2,3,6,7", table.concat(changed, ","))
check("assign again changes nothing", #names.assign(current, mix.buildRules(CASES[1].options)) == 0)

check("isGenerated", names.isGenerated("R ELEVON") and names.isGenerated("AIL 3")
  and names.isGenerated("TV YAW") and not names.isGenerated("AILX") and not names.isGenerated("")
  and not names.isGenerated("L TOW"))

check("withName adds the name", names.withName("Servo 1", {[0] = "L AIL"}, 0) == "Servo 1 (L AIL)")
check("withName leaves an unnamed servo", names.withName("Servo 2", {[0] = "L AIL", [1] = ""}, 1) == "Servo 2")
check("withName without names", names.withName("Servo 1", nil, 0) == "Servo 1")

-- Wire format (firmware msp.c, MSP2_WING_SERVO_NAMES / SET_SERVO_NAME)
check("clean trims, drops non-printables, caps at 8",
  codec.clean("  Elevator!xyz") == "Elevator" and codec.clean("L\1 AIL ") == "L AIL"
  and codec.clean(nil) == "" and codec.clean("ABCDEFG HIJ") == "ABCDEFG", codec.clean("ABCDEFG HIJ"))
local payload = codec.encode(2, " ELEV ")
check("encode: servo then the cleaned name", table.concat(payload, ",") == "2,69,76,69,86", table.concat(payload, ","))
check("encode: an empty name clears", table.concat(codec.encode(5, ""), ",") == "5")

local msg = codec.buildReadMessage()
local buf = {}
for i, b in ipairs(msg.simulatorResponse) do buf[i] = b end
local decoded, count = codec.decode(buf)
check("decode the simulator response", count == 24 and decoded[0] == "L AIL" and decoded[3] == "RUDDER"
  and decoded[4] == "" and decoded[23] == "", tostring(count) .. " " .. tostring(decoded[0]))
local full = {1, 8, 65, 66, 67, 68, 69, 70, 71, 72}
decoded = codec.decode(full)
check("decode an 8-character name", decoded[0] == "ABCDEFGH", decoded[0])

print(string.format("%d checks, %d failures", checks, failures))
os.exit(failures == 0 and 0 or 1)
